<template>
  <div class="main-data-container">

    <!-- ── 1. Лёгкий прелоадер (данные уже есть в кеше) ── -->
    <transition name="fade">
      <div class="light-preloader" v-if="isCacheLoad">
        <div class="lp-bar">
          <div class="lp-bar-fill"></div>
        </div>
        <div class="lp-text">{{ $t('common.cacheLoading') }}</div>
      </div>
    </transition>

    <!-- ── 2. Полный степпер (первая загрузка) ─────────── -->
    <div class="loader-wrap" v-if="!isLoad && !isCacheLoad">
      <div class="spinner-only" v-if="!isPogress">
        <div class="orbit-spinner">
          <div class="orbit"></div>
          <div class="orbit"></div>
          <div class="orbit"></div>
        </div>
      </div>
      <div class="stepper-load" v-if="isPogress">
        <div class="top-bar">
          <div class="top-bar-fill" :style="{ width: progressWidth }"></div>
        </div>
        <div class="loader-title">{{ $t('common.loadingWait') }}</div>
        <div class="steps">
          <template v-for="(step, i) in loaderSteps" :key="step.key">
            <div v-if="i > 0" class="step-line">
              <div class="step-line-fill" :style="{ width: lineWidth(i) }"></div>
            </div>
            <div class="step">
              <div class="step-icon" :class="stepState(step.key)">
                <div v-if="stepState(step.key) === 'active'" class="step-spinner"></div>
                <span v-else-if="stepState(step.key) === 'done'">✓</span>
                <span v-else class="step-arrow">↓</span>
              </div>
              <div class="step-label" :class="stepState(step.key)">{{ step.label }}</div>
            </div>
          </template>
        </div>
      </div>
    </div>

    <!-- ── 3. Контент ─────────────────────────────────── -->
    <transition name="fade">
      <div class="main-data-body" v-if="isLoad">

        <!-- Кнопка выбора периода -->
        <div class="choosed-period">
          <div class="period-wrap">
            <button class="period-btn" :class="{ 'active-btn': periodOpen }" @click="periodOpen = !periodOpen">
              📅
              <div class="period-tooltip">{{ userTimeDate }}</div>
            </button>
            <div class="period-dropdown" v-if="periodOpen">
              <div class="dropdown-header">{{ $t('common.period') }}</div>
              <div
                  v-for="p in datePeriod" :key="p"
                  class="period-option" :class="{ active: p === userTimeDate }"
                  @click="userTimeDate = p; periodOpen = false"
              >
                {{ p }}
                <span v-if="p === userTimeDate" class="period-check">✓</span>
              </div>
            </div>
          </div>
        </div>

        <!-- Карточки по компании -->
        <div class="cards">
          <MetricCard metric-key="revenue"    :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="services"   :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="trafic"     :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="conversion" :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="check"      :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="count"      :selected-date="userTimeDate" :all-data="companyData"/>
          <MetricCard metric-key="credit"     :selected-date="userTimeDate" :all-data="companyData"/>
        </div>

        <div class="divider"></div>

        <!-- Онлайн-каналы (интернет-магазин + мономаркет) -->
        <OnlineChannelsCard
            :selected-date="userTimeDate"
            :company-data="companyData"
        />

        <div class="divider"></div>

        <!-- Графики -->
        <div class="charts">
          <AllManagersChart :selected-date="userTimeDate"/>
          <div class="divider"></div>
          <TraficManagerChart :selected-date="userTimeDate"/>
          <div class="divider"></div>
          <div class="secondary-manager-charts">
            <CheckManagersChart :selected-date="userTimeDate"/>
            <ConverciaManagersChart :selected-date="userTimeDate"/>
          </div>
          <div class="divider"></div>
          <div class="secondary-manager-charts">
            <CreditManagerChart :selected-date="userTimeDate"/>
            <CountManagersChart :selected-date="userTimeDate"/>
          </div>
        </div>

        <div class="divider"></div>

        <!-- ── Сопутствующие товары ──────────────────── -->
        <div class="sp-section-wrap">
          <SupProdCards :row-data="supProdCompanyRow"/>
          <SupProdChart
              :items="supProdManagerItems"
              :period="userTimeDate"
              :chart-title="$t('supProd.chartTitle')"          />
        </div>

        <div class="divider"></div>

        <div class="summ-card">
          <SummaryCardComponent :selected-date="userTimeDate"/>
        </div>
      </div>
    </transition>

    <v-snackbar v-model="snackbar" color="error" timeout="4000">
      {{ snackbarText }}
    </v-snackbar>

  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'
import {MANAGERS, COMPANY_URL} from '@/config/managers.config'

import MetricCard from '@/components/others/MetricCard.vue'
import SummaryCardComponent from '@/components/others/SummaryCardComponent.vue'
import OnlineChannelsCard from '@/components/others/OnlineChannelsCard.vue'

import AllManagersChart from '@/components/chart/AllManagersChart.vue'
import CheckManagersChart from '@/components/chart/CheckManagersChart.vue'
import ConverciaManagersChart from '@/components/chart/ConverciaManagersChart.vue'
import CreditManagerChart from '@/components/chart/CreditManagerChart.vue'
import TraficManagerChart from '@/components/chart/TraficManagerChart.vue'
import CountManagersChart from '@/components/chart/CountManagersChart.vue'
import SupProdCards from '@/components/others/SupProdCards.vue'
import SupProdChart from '@/components/chart/SupProdChart.vue'

export default {
  name: 'MainDataComponent',

  components: {
    MetricCard,
    SummaryCardComponent,
    OnlineChannelsCard,

    AllManagersChart,
    CheckManagersChart,
    ConverciaManagersChart,
    CreditManagerChart,
    TraficManagerChart,
    CountManagersChart,
    SupProdCards,
    SupProdChart,
  },

  data() {
    // Степпер и loadPersonalData генерируются из конфига
    const loaderSteps = [
      {key: 'company', label: this.$t('common.company')},
      ...MANAGERS.map(m => ({key: m.id, label: m.name})),
    ]
    const loadPersonalData = Object.fromEntries(
        loaderSteps.map(s => [s.key, false])
    )

    return {
      isLoad: false,
      isPogress: false,
      isCacheLoad: false,
      snackbar: false,
      snackbarText: '',
      reloadScheduled: false,
      periodOpen: false,
      companyData: [],
      datePeriod: [],
      userTimeDate: '',
      loadPersonalData,
      loaderSteps,
    }
  },

  computed: {

    // ── Данные сопутствующих товаров ──────────────────
    // Читаем из реактивного this.companyData (не из dataStore!)
    supProdCompanyRow() {
      if (!this.companyData.length) return null
      return this.companyData.find(r => r.time === this.userTimeDate) || this.companyData[0] || null
    },

    supProdManagerItems() {
      return MANAGERS.map(m => {
        const data = dataStore.getManagerData(m.id)
        if (!data) return null
        const row = this.userTimeDate
            ? data.find(r => r.time === this.userTimeDate)
            : data[0]
        if (!row) return null
        return {
          name:     m.name,
          smart:    row.smart    ?? 0,
          note:     row.note     ?? 0,
          tv:       row.tv       ?? 0,
          sup_prod: row.sup_prod ?? 0,
          poslug:   row.poslug   ?? 0,
        }
      }).filter(Boolean)
    },

    progressWidth() {
      const done = Object.values(this.loadPersonalData).filter(Boolean).length
      return Math.round((done / this.loaderSteps.length) * 100) + '%'
    },
  },

  methods: {
    stepState(key) {
      if (this.loadPersonalData[key]) return 'done'
      const keys = Object.keys(this.loadPersonalData)
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === key ? 'active' : 'pending'
    },

    lineWidth(i) {
      const keys = Object.keys(this.loadPersonalData)
      const prevKey = keys[i - 1]
      if (this.loadPersonalData[prevKey]) return '100%'
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === prevKey ? '40%' : '0%'
    },

    async getRequest() {
      const cached = dataStore.getCompanyData()

      if (cached && !dataStore.isStale()) {
        this.companyData = [...cached]
        this.getAllPeriods()
        this.isCacheLoad = true
        setTimeout(() => {
          this.isCacheLoad = false
          this.isLoad = true
          localStorage.setItem('checkLoadStatus', 'loaded')
        }, 600)
        return
      }

      this.isPogress = true

      try {
        // Загрузка компании
        try {
          const res      = await fetch(COMPANY_URL)
          const response = await res.json()
          dataStore.setCompanyData(response.info)
          this.companyData = [...response.info]
          this.getAllPeriods()
          this.loadPersonalData.company = true
        } catch (error) {
          this.snackbarText = this.$t('common.errorCompany') + '. ' + this.$t('common.autoReload') + '...'
          this.snackbar = true
          console.error(error)
          this._scheduleReload()
        }

        // Загрузка менеджеров — цикл по конфигу
        for (const manager of MANAGERS) {
          try {
            const res      = await fetch(manager.url)
            const response = await res.json()
            dataStore.setManagerData(manager.id, response[manager.dataKey])
            this.loadPersonalData[manager.id] = true
          } catch (error) {
            this.snackbarText = this.$t('common.errorManager') + ' ' + manager.name + '. ' + this.$t('common.autoReload') + '...'
            this.snackbar = true
            console.error(error)
            this._scheduleReload()
          }
        }

      } catch (e) {
        console.error(e)
      }
    },

    _scheduleReload() {
      if (this.reloadScheduled) return
      this.reloadScheduled = true
      setTimeout(() => window.location.reload(), 5000)
    },

    getAllPeriods() {
      const periods = [...new Set(this.companyData.map(item => item.time))].reverse()
      this.datePeriod = [...periods]
      this.userTimeDate = periods[0] || ''
    },

  },

  watch: {
    loadPersonalData: {
      handler(val) {
        if (Object.values(val).every(Boolean)) {
          setTimeout(() => {
            this.isLoad = true
            localStorage.setItem('checkLoadStatus', 'loaded')
          }, 800)
        }
      },
      deep: true,
    },
  },


  mounted() {
    this.getRequest()
  },

  beforeUnmount() {
    localStorage.removeItem('checkLoadStatus')
  },
}
</script>

