<template>
  <div class="online-channels" v-if="row && hasData">

    <!-- Интернет-магазин -->
    <div class="channel-card" style="border-left: 2px solid #378ADD;">
      <div class="ch-header">
        <div class="ch-title-wrap">
          <i class="mdi mdi-cart-outline" style="font-size:16px; color:#378ADD;" aria-hidden="true"></i>
          <span class="ch-title">{{ $t('metrics.im') }}</span>
        </div>
        <span class="badge" :class="imPlanClass">{{ imPct }}%</span>
      </div>
      <div class="ch-period">{{ row.time }}</div>

      <div class="ch-fact">
        {{ formatNum(im.f) }} <span class="ch-currency">грн</span>
      </div>
      <div class="ch-sub">{{ $t('common.plan') }} {{ formatNum(im.p) }}</div>
      <div class="ch-sub">{{ $t('common.lastYear') }} {{ im.past ? formatNum(im.past) : '—' }}</div>

      <div class="progress-wrap">
        <div class="progress-header">
          <span class="progress-label">{{ $t('common.fulfillPlan') }}</span>
          <span class="progress-pct" style="color:#378ADD;">{{ imPct }}%</span>
        </div>
        <div class="progress-track">
          <div class="progress-fill" :style="{ width: Math.min(imPct, 100) + '%', background: '#378ADD' }"></div>
        </div>
        <div class="progress-hint">{{ formatShort(im.f) }} {{ $t('common.mln') }} {{ $t('summary.of') }} {{ formatShort(im.p) }} {{ $t('common.mln') }}</div>
      </div>

      <div class="ch-tags" v-if="im.past">
        <span class="tag" :class="imYoyClass">{{ imYoy >= 0 ? '+' : '' }}{{ imYoy }}% {{ $t('common.toLastYear') }}</span>
      </div>
    </div>

    <!-- Мономаркет -->
    <div class="channel-card" style="border-left: 2px solid #1D9E75;">
      <div class="ch-header">
        <div class="ch-title-wrap">
          <i class="mdi mdi-store-outline" style="font-size:16px; color:#1D9E75;" aria-hidden="true"></i>
          <span class="ch-title">{{ $t('metrics.mono') }}</span>
        </div>
        <span class="badge" :class="monoPlanClass">{{ monoPct }}%</span>
      </div>
      <div class="ch-period">{{ row.time }}</div>

      <div class="ch-fact">
        {{ formatNum(mono.f) }} <span class="ch-currency">грн</span>
      </div>
      <div class="ch-sub">{{ $t('common.plan') }} {{ formatNum(mono.p) }}</div>
      <div class="ch-sub">{{ $t('common.lastYear') }} {{ mono.past ? formatNum(mono.past) : '—' }}</div>

      <div class="progress-wrap">
        <div class="progress-header">
          <span class="progress-label">{{ $t('common.fulfillPlan') }}</span>
          <span class="progress-pct" style="color:#1D9E75;">{{ monoPct }}%</span>
        </div>
        <div class="progress-track">
          <div class="progress-fill" :style="{ width: Math.min(monoPct, 100) + '%', background: '#1D9E75' }"></div>
        </div>
        <div class="progress-hint">{{ formatShort(mono.f) }} {{ $t('common.mln') }} {{ $t('summary.of') }} {{ formatShort(mono.p) }} {{ $t('common.mln') }}</div>
      </div>

      <div class="ch-tags">
        <span v-if="mono.past" class="tag" :class="monoYoyClass">{{ monoYoy >= 0 ? '+' : '' }}{{ monoYoy }}% {{ $t('common.toLastYear') }}</span>
        <span v-else class="tag tag-muted">{{ $t('metrics.monoNoData') }}</span>
      </div>
    </div>

  </div>
</template>

<script>
function pctColor(p) {
  if (p >= 100) return 'badge-green'
  if (p >= 85)  return 'badge-yellow'
  return 'badge-red'
}

function yoyColor(v) {
  return v >= 0 ? 'tag-green' : 'tag-red'
}

export default {
  name: 'OnlineChannelsCard',

  props: {
    selectedDate: { type: String, default: '' },
    companyData:  { type: Array,  default: () => [] },
  },

  computed: {
    row() {
      if (!this.companyData.length) return null
      return this.selectedDate
          ? this.companyData.find(r => r.time === this.selectedDate) || null
          : this.companyData[0] || null
    },

    im() {
      if (!this.row) return { f: 0, p: 0, past: 0 }
      return {
        f:    Number(this.row.im_f)    || 0,
        p:    Number(this.row.im_p)    || 0,
        past: Number(this.row.im_past) || 0,
      }
    },

    mono() {
      if (!this.row) return { f: 0, p: 0, past: 0 }
      return {
        f:    Number(this.row.mono_f)    || 0,
        p:    Number(this.row.mono_p)    || 0,
        past: Number(this.row.mono_past) || 0,
      }
    },

    // Показываем блок только если есть хоть какие-то данные
    hasData() {
      return this.im.f > 0 || this.im.p > 0 || this.mono.f > 0 || this.mono.p > 0
    },

    imPct()  { return this.im.p  ? Math.round((this.im.f  / this.im.p)  * 1000) / 10 : 0 },
    monoPct(){ return this.mono.p ? Math.round((this.mono.f / this.mono.p) * 1000) / 10 : 0 },

    imYoy()  { return this.im.past  ? Math.round(((this.im.f  - this.im.past)  / this.im.past)  * 100) : 0 },
    monoYoy(){ return this.mono.past ? Math.round(((this.mono.f - this.mono.past) / this.mono.past) * 100) : 0 },

    imPlanClass()   { return pctColor(this.imPct)   },
    monoPlanClass() { return pctColor(this.monoPct) },
    imYoyClass()    { return yoyColor(this.imYoy)   },
    monoYoyClass()  { return yoyColor(this.monoYoy) },
  },

  methods: {
    formatNum(n) {
      return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ' ')
    },
    formatShort(n) {
      return (Math.round(n / 100000) / 10).toFixed(1)
    },
  },
}
</script>

