<template>
  <div class="chart-card">
    <div class="chart-header">
      <div class="chart-tag">{{ $t('charts.countShort') }}</div>
      <h2 class="chart-title">{{ $t('charts.countTitle') }}</h2>
      <p class="chart-subtitle">{{ period }}</p>
    </div>
    <div class="legend">
      <div class="leg-item"><span class="leg-dot-fact"></span>{{ $t('charts.factLabel') }}</div>
      <div class="leg-item"><span class="leg-dot-past"></span>{{ $t('charts.lastYearLabel') }}</div>
      <div class="leg-item"><span class="leg-plan-line"></span>{{ $t('charts.avgPlan') }}</div>
    </div>

    <div class="chart-wrap">
      <svg
          class="main-svg"
          :viewBox="`0 0 ${W} ${H}`"
          xmlns="http://www.w3.org/2000/svg"
          preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <filter id="dot-shadow" x="-60%" y="-60%" width="220%" height="220%">
            <feDropShadow dx="0" dy="4" stdDeviation="5" flood-color="rgba(0,0,0,0.18)"/>
          </filter>
        </defs>

        <!-- Горизонтальные линии сетки -->
        <g v-for="v in gridVals" :key="v">
          <line :x1="PL" :y1="toY(v)" :x2="W - PR" :y2="toY(v)"
                stroke="rgba(148,163,184,0.18)" stroke-width="1"/>
          <text :x="PL - 8" :y="toY(v) + 4"
                font-size="11" fill="#cbd5e1" font-family="Inter, system-ui"
                font-weight="500" text-anchor="end">{{ v.toFixed(2) }}</text>
        </g>

        <!-- Линия среднего плана -->
        <line :x1="PL" :y1="planY" :x2="W - PR" :y2="planY"
              stroke="rgba(99,102,241,0.5)" stroke-width="1.5" stroke-dasharray="6 3"/>
        <text :x="W - PR + 4" :y="planY + 4"
              font-size="9" fill="#6366f1" font-family="Inter, system-ui" font-weight="700">
          {{ $t('charts.avgPlan') }} {{ avgPlan }}
        </text>

        <!-- Lollipops -->
        <g v-for="m in chartManagers" :key="m.name">
          <line :x1="m.cx" :y1="PB_Y" :x2="m.cx" :y2="m.cy + DOT_R"
                :stroke="m.color + '66'" stroke-width="2.5" stroke-linecap="round"/>
          <circle :cx="m.cx" :cy="m.pastCy" r="6"
                  :fill="m.color + '55'" stroke="white" stroke-width="1.5"/>
          <circle :cx="m.cx" :cy="m.cy" :r="DOT_R"
                  :fill="m.color" stroke="white" stroke-width="3" filter="url(#dot-shadow)"/>
          <text :x="m.cx" :y="m.cy + 5"
                font-size="11" font-weight="800" fill="white" text-anchor="middle"
                font-family="Inter, system-ui">{{ m.pct }}%</text>
          <text :x="m.cx" :y="m.cy - DOT_R - 8"
                font-size="13" font-weight="800" :fill="m.color" text-anchor="middle"
                font-family="Inter, system-ui">{{ m.count_f.toFixed(2) }}</text>
        </g>
      </svg>

      <div class="names-row">
        <div v-for="m in chartManagers" :key="m.name" class="name-cell">
          <span class="name-text">{{ m.name }}</span>
          <span class="yoy-badge"
                :style="m.yoy >= 0 ? 'background:#dcfce7;color:#16a34a' : 'background:#fee2e2;color:#dc2626'">
            {{ m.yoy >= 0 ? '▲ +' : '▼ ' }}{{ m.yoy }}%
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'
import {MANAGERS, getManagerColor} from '@/config/managers.config'

const W = 800, H = 260, PL = 36, PR = 70, PT = 40, PB = 20, DOT_R = 22

export default {
  name: 'CountManagersChart',

  props: {
    selectedDate: { type: String, default: '' },
  },

  data() {
    return {
      chartManagers: [],
      period:        '',
      avgPlan:       '—',
      planY:         0,
      gridVals:      [],
      chartMin:      0,
      chartMax:      3,
      W, H, PL, PR, PT, PB, DOT_R,
      PB_Y: H - PB,
    }
  },

  mounted() { this.setData() },

  watch: {
    selectedDate(newVal, oldVal) { if (newVal !== oldVal) this.setData() },
  },

  methods: {
    // Динамический расчёт Y-координаты на основе текущего диапазона данных
    toY(val) {
      const drawH = H - PT - PB
      return PT + drawH - ((val - this.chartMin) / (this.chartMax - this.chartMin)) * drawH
    },

    setData() {
      const sources = MANAGERS.map(m => ({ name: m.name, data: dataStore.getManagerData(m.id) }))

      const result = sources
          .filter(s => Array.isArray(s.data) && s.data.length)
          .map(s => {
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]
            if (!row) return null

            const pct = row.count_p ? Math.round((row.count_f / row.count_p) * 1000) / 10 : 0
            const yoy = row.count_past ? Math.round(((row.count_f - row.count_past) / row.count_past) * 100) : 0

            return {
              name:       s.name,
              color:      getManagerColor(s.name),
              count_f:    row.count_f   ?? 0,
              count_p:    row.count_p   ?? 0,
              count_past: row.count_past ?? 0,
              pct,
              yoy,
            }
          })
          .filter(Boolean)
          .sort((a, b) => b.count_f - a.count_f)

      if (!result.length) return

      // ── Динамический диапазон ───────────────────────────────────
      const allVals = result.flatMap(m => [m.count_f, m.count_p, m.count_past]).filter(v => v > 0)
      const dataMax = Math.max(...allVals)
      const dataMin = Math.min(...allVals)
      const padding = Math.max((dataMax - dataMin) * 0.3, 0.2)

      this.chartMin = Math.max(0, parseFloat((dataMin - padding).toFixed(2)))
      this.chartMax = parseFloat((dataMax + padding).toFixed(2))

      // Сетка: 5 горизонтальных линий равномерно
      const step = (this.chartMax - this.chartMin) / 4
      this.gridVals = Array.from({ length: 5 }, (_, i) =>
          parseFloat((this.chartMin + step * i).toFixed(2))
      )

      // Средний план
      const avg    = result.reduce((s, m) => s + m.count_p, 0) / result.length
      this.avgPlan = avg.toFixed(2)
      this.planY   = this.toY(avg)
      this.period  = this.selectedDate || ''

      // Позиции точек
      const drawW = W - PL - PR
      const step2 = drawW / result.length

      this.chartManagers = result.map((m, i) => ({
        ...m,
        cx:     PL + step2 * i + step2 / 2,
        cy:     this.toY(m.count_f),
        pastCy: this.toY(m.count_past),
      }))
    },
  },
}
</script>

