.leg-dot-past { width: 10px; height: 10px; border-radius: 50%; background: #94a3b8; opacity: 0.55; display: inline-block; flex-shrink: 0; }
.leg-plan-line { width: 20px; height: 0; border-top: 2px dashed rgba(99,102,241,0.5); display: inline-block; flex-shrink: 0; }
